-- Applied in Supabase as 20260912_player_onboarding_rpc_privacy_repair.
-- Kept as a replay-safe migration record.
BEGIN;
CREATE OR REPLACE FUNCTION public.register_my_player(p_payload JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_uid UUID=(SELECT auth.uid());v_profile public.profiles%ROWTYPE;v_player public.players%ROWTYPE;v_dob DATE;v_position_code TEXT=lower(trim(coalesce(p_payload->>'position','')));v_position public.player_position;v_foot public.preferred_foot;v_jersey INTEGER;v_height INTEGER;v_weight NUMERIC;v_name TEXT;v_preferred TEXT;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';END IF;SELECT * INTO v_profile FROM public.profiles WHERE id=v_uid;IF NOT FOUND THEN RAISE EXCEPTION 'Profile not found' USING ERRCODE='P0002';END IF;IF v_profile.role<>'player'::public.user_role THEN RAISE EXCEPTION 'Only player accounts can create a player profile' USING ERRCODE='42501';END IF;
 v_dob=NULLIF(p_payload->>'date_of_birth','')::DATE;v_jersey=NULLIF(p_payload->>'jersey_number','')::INTEGER;v_height=NULLIF(p_payload->>'height_cm','')::INTEGER;v_weight=NULLIF(p_payload->>'weight_kg','')::NUMERIC;v_foot=NULLIF(lower(trim(p_payload->>'preferred_foot')),'')::public.preferred_foot;IF v_dob IS NULL OR v_dob>CURRENT_DATE THEN RAISE EXCEPTION 'Tarikh lahir yang sah diperlukan' USING ERRCODE='22023';END IF;
 v_position=CASE WHEN v_position_code IN('gk','goalkeeper') THEN 'goalkeeper'::public.player_position WHEN v_position_code IN('cb','lb','rb','lwb','rwb','defender') THEN 'defender'::public.player_position WHEN v_position_code IN('dm','cm','am','lm','rm','midfielder') THEN 'midfielder'::public.player_position WHEN v_position_code IN('cf','st','ss','forward') THEN 'forward'::public.player_position ELSE NULL END;IF v_position IS NULL THEN RAISE EXCEPTION 'Posisi pemain diperlukan' USING ERRCODE='22023';END IF;
 v_name=coalesce(nullif(trim(v_profile.full_name),''),'Pemain Baru');v_preferred=coalesce(nullif(trim(p_payload->>'preferred_name'),''),v_name);UPDATE public.profiles SET phone=coalesce(nullif(trim(p_payload->>'phone'),''),phone),updated_at=now() WHERE id=v_uid;
 INSERT INTO public.players(profile_id,full_name,preferred_name,date_of_birth,position,preferred_foot,jersey_number,height_cm,weight_kg,nationality,is_active,profile_visibility,verification_status,profile_completed_at,football_passport_no) VALUES(v_uid,v_name,v_preferred,v_dob,v_position,v_foot,v_jersey,v_height,v_weight,coalesce(nullif(trim(p_payload->>'nationality'),''),'Malaysian'),true,case when p_payload->>'profile_visibility'='private' then 'private' else 'public' end,'unverified',now(),'PP-'||to_char(now(),'YYYY')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))) ON CONFLICT(profile_id) DO UPDATE SET full_name=excluded.full_name,preferred_name=excluded.preferred_name,date_of_birth=excluded.date_of_birth,position=excluded.position,preferred_foot=coalesce(excluded.preferred_foot,public.players.preferred_foot),jersey_number=coalesce(excluded.jersey_number,public.players.jersey_number),height_cm=coalesce(excluded.height_cm,public.players.height_cm),weight_kg=coalesce(excluded.weight_kg,public.players.weight_kg),nationality=coalesce(excluded.nationality,public.players.nationality),profile_visibility=excluded.profile_visibility,profile_completed_at=now(),updated_at=now() RETURNING * INTO v_player;
 INSERT INTO public.player_attribute_state(player_id) VALUES(v_player.id) ON CONFLICT(player_id) DO NOTHING;RETURN jsonb_build_object('ok',true,'player_id',v_player.id,'football_passport_no',v_player.football_passport_no,'verification_status',v_player.verification_status);
END;$$;REVOKE ALL ON FUNCTION public.register_my_player(JSONB) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.register_my_player(JSONB) TO authenticated;
DROP POLICY IF EXISTS "players: public read" ON public.players;DROP POLICY IF EXISTS "Semua pengguna berdaftar boleh baca players" ON public.players;DROP POLICY IF EXISTS "Pemain boleh lihat profil sendiri" ON public.players;DROP POLICY IF EXISTS "Pemain boleh kemaskini profil sendiri" ON public.players;DROP POLICY IF EXISTS "Pemain boleh update data sendiri" ON public.players;CREATE POLICY "player owner read" ON public.players FOR SELECT TO authenticated USING(profile_id=(SELECT auth.uid()));REVOKE SELECT ON public.players FROM anon;GRANT SELECT ON public.players TO authenticated;COMMIT;